from __future__ import annotations

from collections.abc import Callable
from typing import Any

from .events import Event
from .subscriptions import Subscription, SubscriptionList


class EventHub:
    def __init__(self) -> None:
        self._subscriptions = SubscriptionList()

    def subscribe(self, callback: Callable[[Event], object], *, once: bool = False) -> Subscription:
        return self._subscriptions.add(Subscription(callback, once=once))

    def unsubscribe(self, subscription: Subscription) -> None:
        self._subscriptions.remove(subscription)

    def publish(self, event: Event) -> list[object]:
        results: list[object] = []
        for subscription in self._subscriptions:
            if not subscription.active:
                continue
            results.append(subscription.callback(event))
            if subscription.once:
                self.unsubscribe(subscription)
        return results
